  foreach(var choice in d.choices)if(choice.previewLabel!=null)choice.previewLabel.gameObject.SetActive(false);
  d.authoredForwardScale=.82f;foreach(var e in d.encounters){var role=e.actors.Select(a=>a.GetComponent<Chapter45RoleAction>()).FirstOrDefault(a=>a!=null);if(role==null)continue;if(role.role==Chapter45RoleAction.Role.Preacher){e.health=40;foreach(var a in e.actors)a.GetComponent<Chapter45RoleAction>().moveSpeed=3.5f;}if(role.role==Chapter45RoleAction.Role.Promoter)e.health=24;}
  foreach(var h in d.hazards.Where(h=>h.name.StartsWith("Risk route taxi")||h.name.StartsWith("Side delivery")))h.warningDistance=24;
  EditorSceneManager.MarkSceneDirty(d.gameObject.scene);if(!EditorSceneManager.SaveScene(d.gameObject.scene))throw new Exception("Save failed");return new{assets,visualOnlyPavingMeshes=10,addedColliders=0,movedExistingDecorativeWalkers=walkers,worldChoiceTextHidden=true,hudChoiceUnchanged=true,forwardScale=d.authoredForwardScale,expectedOrdinarySpeed=7.8f*d.authoredForwardScale,weakCrowdHealth=8,preacherHealth=40,promoterHealth=24,reason="246s native run was short of approximately300s; movement and encounter readability tuned before new replay"};}
